import{_ as i,a0 as l,w as p,s as d,ao as s,I as a,x as e,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"在终端上访问网站和下载文件 | LCTT x X-CMD","titleTemplate":false,"description":"在终端上访问网站和下载文件 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在终端上访问网站和下载文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在终端上访问网站和下载文件 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/5 Command Line Tools for Downloading Files／Torrents and Browsing Websites","title":"在终端上访问网站和下载文件","tag":"201404","desc":""},"relativePath":"201404/5 Command Line Tools for Downloading Files／Torrents and Browsing Websites.md","filePath":"[post].md"}'),g={name:"201404/5 Command Line Tools for Downloading Files／Torrents and Browsing Websites.md"};function m(w,t,c,T,h,u){const n=l("Link");return p(),d("div",null,[t[14]||(t[14]=s(`<h1 id="在终端上访问网站和下载文件" tabindex="-1">在终端上访问网站和下载文件 <a class="header-anchor" href="#在终端上访问网站和下载文件" aria-label="Permalink to “在终端上访问网站和下载文件”">​</a></h1><p>Linux 命令行工具很牛逼，Linux 命令行以及一些第三方应用让 Linux 变得更牛逼。Linux 命令行工具可以用于下载种子和文件，可以上网冲浪。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Command-Line-Internet-Tools.jpg" alt="5 Command Line Internet Tools"></p><p>本文推荐的<strong>5个强悍的上网工具</strong>方便实用，是居家旅行的必备物品。</p><h3 id="_1-rtorrent" tabindex="-1">1. rTorrent <a class="header-anchor" href="#_1-rtorrent" aria-label="Permalink to “1. rTorrent”">​</a></h3><p>rTorrent 基于文本的 Torrent 客户端，用 C++ 调制而成，我们的目标是高性能！我们可运行在标准的 Linux 发行版中，包括 FreeBSD 和 Mac OS X。</p><h4 id="安装-rtorrent" tabindex="-1">安装 rTorrent <a class="header-anchor" href="#安装-rtorrent" aria-label="Permalink to “安装 rTorrent”">​</a></h4><pre><code># apt-get install rtorrent    (基于 APT 的系统，如 Debian，Ubuntu)

# yum install rtorrent        (基于 YUM 的系统，如 RHEL，Fedora)
</code></pre><p>检查有没有安装成功，运行下面命令试试：</p><pre><code># rtorrent
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/rTorrent.jpeg" alt="rTorrent Command Line Tool"></p><h4 id="rtorrent-的用法" tabindex="-1">rTorrent 的用法 <a class="header-anchor" href="#rtorrent-的用法" aria-label="Permalink to “rTorrent 的用法”">​</a></h4><p>下面是 rTorrent 比较常用的功能：</p><ul><li><strong>CTRL+ q</strong> – 退出 rTorrent。</li><li><strong>CTRL+ s</strong> – 开始下载。</li><li><strong>CTRL+ d</strong> – 暂停下载任务，或删除己被暂停的下载任务。</li><li><strong>CTRL+ k</strong> – 关闭一个正在下载的任务</li><li><strong>CTRL+ r</strong> – 在开始上传、下载之前，使用 Hash 检查文件，确保文件的完整性。</li><li><strong>CTRL+ q</strong> – 按再次这个组合键，rTorrent 无条件退出。</li><li><strong>Left Arrow Key</strong> – 回退到上个页面。</li><li><strong>Right Arrow Key</strong> – 前进到下个页面。</li></ul><h3 id="_2-wget" tabindex="-1">2. Wget <a class="header-anchor" href="#_2-wget" aria-label="Permalink to “2. Wget”">​</a></h3><p><strong>Wget</strong> 是一个 GNU 项目，它的名称参考了 World Wide Web (<strong>WWW</strong>)。Wget 在递归下载方面做得很好，你可以将整个网站的内容都下到本地，然后访问本地的 <strong>HTML</strong> 文件。它支持多种操作系统：<strong>Windows，Mac，Linux</strong>。它支持多种协议，可通过 <strong>HTTP，HTTPS 和 FTP</strong> 下载文件。它可以对整个网站做一个镜像（完全将目标网站的文件下载到本机），支持代理，支持断点传输（即下载可暂停）。</p><h4 id="安装-wget" tabindex="-1">安装 Wget <a class="header-anchor" href="#安装-wget" aria-label="Permalink to “安装 Wget”">​</a></h4><p><strong>Wget</strong> 也是一个 GNU 项目，在标准 Linux 发行版中都有内置，就是说你不用下载安装它就可以使用了。万一，它没有被默认安装，你也可以通过 <strong>APT</strong> 或 <strong>YUM</strong> 安装。</p><pre><code># apt-get install wget    (基于 APT 的系统，如 Debian，Ubuntu)

# yum install wget        (基于 YUM 的系统，如 RHEL，Fedora)
</code></pre><h4 id="wget-的用法" tabindex="-1">Wget 的用法 <a class="header-anchor" href="#wget-的用法" aria-label="Permalink to “Wget 的用法”">​</a></h4><p>下载一个文件：</p><pre><code># wget http://www.website-name.com/file
</code></pre><p>下载整个网站：</p><pre><code># wget -r http://www.website-name.com
</code></pre><p>下载指定类型的文件（比如 PDF 和 PNG）：</p><pre><code># wget -r -A png,pdf http://www.website-name.com
</code></pre><p>下面是一张 Wget 的截图，我们正在把 <strong>Yahoo.com</strong> 网站整个都镜像下来。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Wget.jpeg" alt="Wget Command Line File Download"></p>`,28)),a("p",null,[t[1]||(t[1]=e("关于 wget 的更多用法，参考",-1)),r(n,{href:"http://www.tecmint.com/10-wget-command-examples-in-linux/"},{default:o(()=>[...t[0]||(t[0]=[e("Wget 的10个的用法",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[15]||(t[15]=s(`<h3 id="_3-curl" tabindex="-1">3. cURL <a class="header-anchor" href="#_3-curl" aria-label="Permalink to “3. cURL”">​</a></h3><p><strong>cURL</strong> 是一个客户端工具，支持多种文件传输协议，比如 <strong>FTP, HTTP, FTPS, TFTP, TELNET, IMAP, POP3</strong> 等等。不像 wget 等工具，cURL 只是一个单纯的下载器，支持 <strong>LDAP, POP3</strong>，支持代理下载，支持断点续传。</p><h4 id="安装-curl" tabindex="-1">安装 cURL <a class="header-anchor" href="#安装-curl" aria-label="Permalink to “安装 cURL”">​</a></h4><p>大多数发行版都默认安装了 cURL，如果没有，可通过 <strong>apt</strong> 或 <strong>yum</strong> 下载：</p><pre><code># apt-get install curl    (基于 APT 的系统，如 Debian，Ubuntu)

# yum install curl        (基于 YUM 的系统，如 RHEL，Fedora)
</code></pre><h4 id="curl-基本用法" tabindex="-1">cURL 基本用法 <a class="header-anchor" href="#curl-基本用法" aria-label="Permalink to “cURL 基本用法”">​</a></h4><pre><code># curl www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl.jpeg" alt="Curl Data Download"></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl-2.jpeg" alt="Curl Download"></p><h3 id="_4-w3m" tabindex="-1">4. w3m <a class="header-anchor" href="#_4-w3m" aria-label="Permalink to “4. w3m”">​</a></h3><p>W3m 是基于文本的网页浏览器，使用 GPL 协议，支持 tables, frames, color, SSL 连接，支持内嵌图片，以快速闻名。</p><h4 id="安装-w3m" tabindex="-1">安装 w3m <a class="header-anchor" href="#安装-w3m" aria-label="Permalink to “安装 w3m”">​</a></h4><p>W3m 也是大多数发行版的默认配置，也可通过 <strong>apt</strong> 或 <strong>yum</strong> 安装。</p><pre><code># apt-get install w3m    (基于 APT 的系统，如 Debian，Ubuntu)

# yum install w3m        (基于 YUM 的系统，如 RHEL，Fedora)
</code></pre><h4 id="w3m-的基本用法" tabindex="-1">w3m 的基本用法 <a class="header-anchor" href="#w3m-的基本用法" aria-label="Permalink to “w3m 的基本用法”">​</a></h4><pre><code># w3m www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/w3m.jpeg" alt="w3m Text Based Web Browser"></p><h3 id="_5-elinks" tabindex="-1">5. Elinks <a class="header-anchor" href="#_5-elinks" aria-label="Permalink to “5. Elinks”">​</a></h3><p><strong>Elinks</strong> 是一个免费的基于本文的网页浏览器，支持 <strong>HTTP</strong>，支持 <strong>HTTP Cookie</strong>，支持 <strong>Perl</strong> 和 <strong>Ruby</strong> 写的脚本，支持网页标签，支持鼠标，可彩色显示页面，支持 <strong>HTTP, FTP，SMB，IPv4，IPv6</strong>。</p><h4 id="安装-elinks" tabindex="-1">安装 Elinks <a class="header-anchor" href="#安装-elinks" aria-label="Permalink to “安装 Elinks”">​</a></h4><p>大多数发行版已经默认安装了 Elinks，如果没有，通过 <strong>apt</strong> 或 <strong>yum</strong> 安装。</p><pre><code># apt-get install elinks    (基于 APT 的系统，如 Debian，Ubuntu)

# yum install elinks        (基于 YUM 的系统，如 RHEL，Fedora)
</code></pre><h4 id="elinks的基本用法" tabindex="-1">Elinks的基本用法 <a class="header-anchor" href="#elinks的基本用法" aria-label="Permalink to “Elinks的基本用法”">​</a></h4><pre><code>elinks www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Elinks.jpeg" alt="Elinks Command Line Web Browsing"></p><hr>`,26)),a("p",null,[t[4]||(t[4]=e("via: ",-1)),r(n,{href:"http://www.tecmint.com/command-line-tools-for-downloading-file-and-browsing-websites/"},{default:o(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/command-line-tools-for-downloading-file-and-browsing-websites/",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=e("译者：",-1)),r(n,{href:"https://github.com/bazz2"},{default:o(()=>[...t[5]||(t[5]=[e("bazz2",-1)])]),_:1}),t[8]||(t[8]=e(" 校对：",-1)),r(n,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:o(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原创翻译，",-1)),r(n,{href:"http://linux.cn/"},{default:o(()=>[...t[10]||(t[10]=[e("Linux中国",-1)])]),_:1}),t[13]||(t[13]=e(" 荣誉推出",-1))])])}const f=i(g,[["render",m]]);export{P as __pageData,f as default};
